create or replace TABLE LDL_DATA_PRODUCTION.CORE_DIM.T_DIM_CALENDAR_WEEK_2 (
	CAL_WEEK NUMBER(38,0) NOT NULL COMMENT 'The week as a number of the form YYYYWW. YYYY is the year of the week and WW is the number of the week within the calendar_2 year. Week 1 is the first week in the calendar_2 year containing at least 4 days.',
	WEEK_OF_CAL_YEAR NUMBER(38,0) COMMENT 'The number of the week within the calendar_2 year, i.e. a number between 1 and 53. Week 1 is the first week in the calendar_2 year containing at least 4 days, therefore the first week containing a Thursday.',
	WEEK_OF_BUS_YEAR NUMBER(38,0) COMMENT 'The number of the week within the business year, i.e. a number between 1 and 53. Week 1 is the first week in the business year containing at least 4 days, therefore the first week containing a Thursday.',
	CAL_WEEK_SHORT_NAME VARCHAR(100) NOT NULL COMMENT 'A short version of the name of the week in group language, i.e. in German, in the format \""KW nn\"" with nn being the week of the year.',
	CAL_WEEK_SHORT_NAME_DE VARCHAR(100) COMMENT 'A short version of the name of the week in German in the format \""KW nn\"" with nn being the week of the year.',
	CAL_WEEK_SHORT_NAME_EN VARCHAR(100) COMMENT 'A short version of the name of the week in English in the format \""week nn\"" with nn being the week of the year.',
	CAL_WEEK_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the week in group language, i.e. in German, in the format \""YYYY KW nn\"" with YYYY being the year and nn being the week of the year.',
	CAL_WEEK_NAME_DE VARCHAR(100) COMMENT 'The name of the week in German in the format \""YYYY KW nn\"" with YYYY being the year and nn being the week of the year.',
	CAL_WEEK_NAME_EN VARCHAR(100) COMMENT 'The name of the week in English in the format \""YYYY week nn\"" with YYYY being the year and nn being the week of the year.',
	CAL_WEEK_BEGIN_PART_WEEK NUMBER(38,0) NOT NULL COMMENT 'The first partial week (inclusive) of the week as a number in the form YYYYWWn. Eg. 2020531.',
	CAL_WEEK_END_PART_WEEK NUMBER(38,0) NOT NULL COMMENT 'The last partial week (inclusive) of the week as a number in the form YYYYWWn. Eg. 2020532. If the week does not span two months, this is the same as cy_week_begin_week_part.',
	CAL_WEEK_BEGIN_DT DATE NOT NULL COMMENT 'The first day of the week - i.e. the Monday - in the form YYYY-MM_2-DD. Eg. 2020-12-28.',
	CAL_WEEK_END_DT DATE NOT NULL COMMENT 'The last day of the week - i.e. the Sunday - in the form YYYY-MM_2-DD. Eg. 2021-01-03. ',
	CAL_WEEK_PART_WEEK_CNT NUMBER(38,0) COMMENT 'The number of partial weeks in this week, i.e. 1 or 2.',
	PREV_1W_CAL_WEEK NUMBER(38,0) NOT NULL COMMENT 'The previous week as a number in the form YYYYWW. Eg. 202052. ',
	PREV_1Y1W_CAL_WEEK NUMBER(38,0) NOT NULL COMMENT 'The week 1 year and 1 week (= 371 days = 53 weeks) ago as a number in the form YYYYWW. Eg. 202001.',
	PREV_1Y_CAL_WEEK NUMBER(38,0) NOT NULL COMMENT 'The week 1 year (= 364 days = 52 weeks) ago as a number in the form YYYYWW. Eg. 202001.',
	PREV_2Y_CAL_WEEK NUMBER(38,0) NOT NULL COMMENT 'The week 2 years (= 728 days = 104 weeks) ago as a number in the form YYYYWW. Eg. 201901. ',
	PREV_3Y_CAL_WEEK NUMBER(38,0) NOT NULL COMMENT 'The week 3 years (= 1092 days = 156 weeks) ago as a number in the form YYYYWW. Eg. 201801.',
	PREV_4Y_CAL_WEEK NUMBER(38,0) NOT NULL COMMENT 'The week 4 years (= 1456 days = 208 weeks) ago as a number in the form YYYYWW. Eg. 201701.',
	PREV_5Y_CAL_WEEK NUMBER(38,0) NOT NULL COMMENT 'The week 5 years (= 1820 days = 260 weeks) ago as a number in the form YYYYWW. Eg. 201601.',
	CURR_CAL_WEEK_FG BOOLEAN NOT NULL COMMENT 'This indicator is set for the current calendar_2 week.',
	CAL_WEEK_OFFSET NUMBER(38,0) COMMENT 'The difference in weeks between this week and the current week. So if current week is 202053 then the offset is 0 for 202053, -1 for 202052 and +1 for 202101. ',
	DWH_CREATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
	DWH_UPDATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created or last updated.',
	DWH_LOAD_ID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier of the batch load which has done the last update to this record. (Closing a record in history without updating any payload columns does not trigger an update of the dwh_load_id.)',
	DWH_NODE_CD VARCHAR(20) NOT NULL COMMENT 'The code for the source system (or slice of source system) from which this record was loaded.',
	constraint PK_T_DIM_CALENDAR_WEEK primary key (CAL_WEEK)
)COMMENT='Calendar_2 weeks. A week may span two months or two years. A week is considered part of the year, into which most of its days fall.'
;